import { Injectable } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { environment } from '../../environments/environment';
import { firstValueFrom } from 'rxjs';

export interface AuthUser {
  id: number;
  name: string;
  email: string;
  phone: string;
  avatar: string | null;
  email_verified: boolean;
  phone_verified: boolean;
}

@Injectable({ providedIn: 'root' })
export class AuthService {
  private token: string | null = null;
  user: AuthUser | null = null;

  constructor(private http: HttpClient) {}

  get accessToken(): string | null {
    return this.token;
  }

  private setSession(token: string, user?: AuthUser) {
    this.token = token;
    if (user) this.user = user;
  }

  async register(name: string, email: string, phone: string, password: string, avatar?: File) {
    const formData = new FormData();
    formData.append('name', name);
    formData.append('email', email);
    formData.append('phone', phone);
    formData.append('password', password);
    if (avatar) formData.append('avatar', avatar);

    const res: any = await firstValueFrom(
      this.http.post(`${environment.apiUrl}/auth/register`, formData)
    );
    this.setSession(res.token, res.user);
    return res.user;
  }

  async login(email: string, password: string) {
    const res: any = await firstValueFrom(
      this.http.post(`${environment.apiUrl}/auth/login`, { email, password })
    );
    this.setSession(res.token, res.user);
    return res.user;
  }

  async sendOtp() {
    return firstValueFrom(this.http.post(`${environment.apiUrl}/auth/send-otp`, {}));
  }

  async verifyOtp(code: string) {
    return firstValueFrom(this.http.post(`${environment.apiUrl}/auth/verify-otp`, { code }));
  }

  async forgotPassword(email: string) {
    return firstValueFrom(this.http.post(`${environment.apiUrl}/auth/forgot-password`, { email }));
  }

  async resetPassword(token: string, newPassword: string) {
    return firstValueFrom(this.http.post(`${environment.apiUrl}/auth/reset-password`, { token, newPassword }));
  }

  async me() {
    const user: any = await firstValueFrom(this.http.get(`${environment.apiUrl}/auth/me`));
    this.user = user;
    return user;
  }

  async refresh(): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(this.http.post(`${environment.apiUrl}/auth/refresh`, {}));
      this.setSession(res.token);
      return true;
    } catch {
      this.token = null;
      this.user = null;
      return false;
    }
  }

  async logout() {
    try {
      await firstValueFrom(this.http.post(`${environment.apiUrl}/auth/logout`, {}));
    } finally {
      this.token = null;
      this.user = null;
    }
  }
}
